mkdir -p /tmp/work && cat > /tmp/work/r.py <<'EOF'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None;log=[]
def token():
    global tok
    while True:
        try:
            r=urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST",data=b""));tok=json.load(r)["token"];return
        except urllib.error.HTTPError as e:
            log.append(("token",e.code));time.sleep(float(e.headers.get("Retry-After") or 1))
def get(p):
    for _ in range(200):
        if not tok: token()
        try:
            return json.load(urllib.request.urlopen(urllib.request.Request(B+p,headers={"Authorization":"Bearer "+tok})))
        except urllib.error.HTTPError as e:
            log.append((p,e.code))
            if e.code==401: token()
            elif e.code==404 and p.startswith("/customers"): return None
            elif e.code==429: time.sleep(float(e.headers.get("Retry-After") or 1))
            else: time.sleep(0.5)
        except Exception as e: log.append((p,str(e)));time.sleep(0.5)
    raise SystemExit("fail "+p)
seen={};dups=0;p="/orders?page=1";pages=0
while p:
    d=get(p);pages+=1
    for o in d["items"]:
        if o["id"] in seen:
            dups+=1
            if seen[o["id"]]!=o: print("DIFF",o,seen[o["id"]])
        else: seen[o["id"]]=o
    p=d["next"]
print("pages",pages,d["total_pages"],"orders",len(seen))
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};reg={k:0 for k in["north","south","east","west"]};n=0;odd=set()
for o in seen.values():
    if o["status"]!="shipped": odd.add(o["status"]);continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None: odd.add("naive "+o["placed_at"]);t=t.replace(tzinfo=timezone.utc)
    t=t.astimezone(timezone.utc)
    if not(lo<=t<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    cu=cust[c]
    if cu is None: print("missing cust",o);continue
    v=(o["amount_cents"]*(100-cu["discount_pct"])*2+100)//200
    reg[cu["region"]]+=v;n+=1
print("statuses",odd);print({e for e in log if 1})
r={"total_cents":sum(reg.values()),"order_count":n,"duplicates_skipped":dups,"by_region":reg}
print(r);json.dump(r,open("/workspace/result.json","w"),indent=2)
EOF
